expr:
COALESCE(
  CAST(
    LEAD(c.EffectiveDate) OVER (
      PARTITION BY c.CompanyID
      ORDER BY c.EffectiveDate
    ) - INTERVAL 1 DAY
    AS DATE
  ),
  DATE '9999-12-31'
)

CAST(
  COALESCE(
    (SELECT SK_CompanyID FROM DimCompany WHERE CompanyID = DS.CIK AND IsCurrent = TRUE LIMIT 1),
    (SELECT SK_CompanyID FROM DimCompany WHERE Name = DS.CoName AND IsCurrent = TRUE LIMIT 1)
  ) AS INTEGER
)
